"""Interactive first-run setup: `python -m app.setup` writes a working .env.

Only TELEGRAM_BOT_TOKEN and DEVIN_API_KEY are truly required; everything
else either gets a generated secret or stays at its documented default.
The file is written 0600 via an atomic replace, after validation, so a
failed run can never destroy a working configuration.
"""

from __future__ import annotations

import argparse
import getpass
import os
import secrets
import shutil
import sys
import tempfile
from pathlib import Path

_ENV_HEADER = """\
# Generated by `python -m app.setup`. Optional variables keep their
# documented defaults; see .env.example for the full list and
# docs/configuration.md for what each one means.
"""


def _ask(label: str, default: str = "", required: bool = False) -> str:
    while True:
        suffix = f" [{default}]" if default else ""
        try:
            value = input(f"{label}{suffix}: ").strip()
        except EOFError:
            print()
            raise SystemExit(2)
        value = value or default
        if value or not required:
            return value
        print("  required")


def _ask_secret(label: str, hint: str | None = None) -> str:
    while True:
        try:
            value = getpass.getpass(f"{label}: ").strip()
        except EOFError:
            print()
            raise SystemExit(2)
        if value:
            if hint is not None and not value.startswith(hint):
                print(f"  expected a value starting with {hint!r} — try again")
                continue
            return value
        print("  required")


def _confirm(label: str) -> bool:
    try:
        return input(f"{label} [y/N]: ").strip().casefold() in {"y", "yes"}
    except EOFError:
        print()
        raise SystemExit(2)


def collect() -> dict[str, str]:
    """Prompt for every value and return the .env mapping."""
    print("telegram-devin-bridge setup\n")
    env: dict[str, str] = {}
    token = _ask_secret("TELEGRAM_BOT_TOKEN (from @BotFather)")
    while ":" not in token:
        print("  bot tokens look like 123456:ABC-DEF...")
        token = _ask_secret("TELEGRAM_BOT_TOKEN")
    env["TELEGRAM_BOT_TOKEN"] = token
    env["DEVIN_API_KEY"] = _ask_secret(
        "DEVIN_API_KEY (v1 key, starts with apk_)", hint="apk_"
    )

    users = _ask(
        "TELEGRAM_ALLOWED_USERS — comma-separated user ids "
        "(blank = open to ANYONE on Telegram)"
    )
    if users:
        env["TELEGRAM_ALLOWED_USERS"] = users
    elif _confirm("Allow every Telegram user to spend your ACU budget?"):
        env["TELEGRAM_ALLOW_ALL_USERS"] = "true"
    else:
        print("  no allowed users — only admins could talk to the bot; "
              "falling back to TELEGRAM_ALLOW_ALL_USERS=false anyway")

    mode = ""
    while mode not in {"polling", "webhook"}:
        mode = _ask(
            "TELEGRAM_MODE (polling works with no public URL)",
            default="polling",
        ).casefold()
        if mode not in {"polling", "webhook"}:
            print("  enter 'polling' or 'webhook'")
    env["TELEGRAM_MODE"] = mode
    if mode == "webhook":
        url = ""
        while not url.startswith("https://"):
            url = _ask(
                "PUBLIC_BASE_URL (https://… routed to port 8000)",
                required=True,
            )
            if not url.startswith("https://"):
                print("  Telegram webhooks require an https:// URL")
        env["PUBLIC_BASE_URL"] = url

    env["DATABASE_PATH"] = _ask("DATABASE_PATH", default="./bridge.sqlite3")

    # generated once so /notify, /doctor, /admin and webhook verification
    # all work out of the box; webhook secret is written even in polling
    # mode so switching later needs no re-run
    for key in (
        "TELEGRAM_WEBHOOK_SECRET",
        "NOTIFY_SECRET",
        "DOCTOR_SECRET",
        "ADMIN_SECRET",
    ):
        env[key] = secrets.token_urlsafe(24)

    cli = shutil.which("devin")
    if cli:
        print(f"\nfound devin CLI at {cli} — `/platform local` sessions are "
              "available to admins (DEVIN_LOCAL_CLI=devin is the default)")
    return env


def render(env: dict[str, str]) -> str:
    lines = [_ENV_HEADER]
    for key, value in env.items():
        lines.append(f"{key}={value}")
    return "\n".join(lines) + "\n"


def validate(env: dict[str, str]) -> None:
    """Run the collected mapping through the real Settings — as init
    kwargs, so the host's own environment can't shadow what we check."""
    from app.config import Settings

    Settings(**env)


def _write_private(path: Path, content: str) -> None:
    """Write content to path atomically, mode 0600 — a failed or
    interrupted write leaves any existing file untouched."""
    handle, tmp = tempfile.mkstemp(
        dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp"
    )
    try:
        with os.fdopen(handle, "w") as out:
            out.write(content)
        os.chmod(tmp, 0o600)
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="python -m app.setup",
        description="Interactively write a .env for telegram-devin-bridge.",
    )
    parser.add_argument("--path", default=".env", help="target env file")
    parser.add_argument("--force", action="store_true",
                        help="overwrite an existing file without asking")
    args = parser.parse_args(argv)
    path = Path(args.path)

    if (
        path.exists()
        and not args.force
        and not _confirm(f"{path} exists — overwrite it?")
    ):
        return 1

    env = collect()

    # validate before touching the destination — a bad answer must not
    # destroy a working configuration
    try:
        validate(env)
    except Exception as exc:  # noqa: BLE001
        # pydantic str(exc) echoes input= values — that would spill the
        # token and key to stderr, so report field + message only
        errors = getattr(exc, "errors", None)
        if callable(errors):
            detail = "; ".join(
                f"{'.'.join(str(p) for p in e.get('loc', ()))}: {e.get('msg')}"
                for e in errors()
            )
        else:
            detail = type(exc).__name__
        print(f"\nsettings do not validate: {detail}", file=sys.stderr)
        return 1

    _write_private(path, render(env))
    print(f"\nwrote {path} (mode 0600)")

    if path.name != ".env":
        print(
            f"warning: the bridge reads .env — copy or symlink {path} to "
            ".env before starting",
            file=sys.stderr,
        )

    print("next steps:")
    if env.get("TELEGRAM_MODE") == "polling":
        print("  .venv/bin/python -m app.poll")
    else:
        print("  uvicorn app.main:app --host 0.0.0.0 --port 8000")
        print("  .venv/bin/python -m app.set_webhook")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
